/* CSS PART 1 OF 2 */

/* -----------------------------------------
   1. DESIGN TOKENS
----------------------------------------- */

:root {
  color-scheme: light;
  --forest: #203c30;
  --forest-deep: #172d24;
  --sage: #788c70;
  --sage-light: #e8ede3;
  --earth: #a66e48;
  --sand: #f3f0e8;
  --cream: #faf9f5;
  --white: #ffffff;
  --ink: #26342c;
  --muted: #68736b;
  --line: #dce1d8;

  --font-display: "Georgia", "Times New Roman", serif;
  --font-body: "Arial", "Helvetica Neue", sans-serif;

  --container: 1200px;
  --gutter: clamp(22px, 6vw, 84px);
  --section-space: clamp(76px, 10vw, 132px);

  --radius-small: 5px;
  --radius-medium: 12px;
  --radius-large: 22px;

  --shadow-soft: 0 16px 45px rgba(29, 49, 36, 0.09);
  --transition: 220ms ease;
}

/* -----------------------------------------
   2. RESET & ACCESSIBILITY
----------------------------------------- */

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--earth);
  outline-offset: 4px;
}

::selection {
  background: var(--sage);
  color: var(--white);
}

/* -----------------------------------------
   3. SHARED TYPOGRAPHY
----------------------------------------- */

h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--forest-deep);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(3.2rem, 7.6vw, 6.8rem);
}

h2 {
  font-size: clamp(2.4rem, 5vw, 4.3rem);
}

h3 {
  font-size: clamp(1.55rem, 2.5vw, 2.15rem);
}

p {
  margin: 0 0 1.2em;
}

p:last-child {
  margin-bottom: 0;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--sage);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 1px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: 26px;
}

.section-copy {
  max-width: 590px;
  color: var(--muted);
  font-size: 1.05rem;
  line-height: 1.9;
}

.text-accent {
  color: var(--sage);
}

.container {
  width: min(100% - var(--gutter) * 2, var(--container));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

/* -----------------------------------------
   4. HEADER & NAVIGATION
----------------------------------------- */

.site-header {
  position: relative;
  z-index: 20;
  width: 100%;
  background: var(--cream);
  border-bottom: 1px solid rgba(32, 60, 48, 0.09);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
}

.brand {
  display: inline-flex;
  min-width: 190px;
  align-items: center;
  gap: 13px;
}

.brand img {
  width: auto;
  max-width: 190px;
  max-height: 62px;
  object-fit: contain;
  object-position: left center;
}

.brand-name {
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.55rem;
  line-height: 1;
  letter-spacing: -0.04em;
}

.brand-caption {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font-family: var(--font-body);
  font-size: 0.59rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(20px, 3vw, 39px);
}

.primary-nav a {
  position: relative;
  padding-block: 10px;
  color: var(--forest);
  font-size: 0.82rem;
  font-weight: 600;
  transition: color var(--transition);
}

.primary-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 3px;
  left: 0;
  height: 1px;
  background: var(--sage);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.primary-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

.primary-nav a:hover {
  color: var(--sage);
}

/* -----------------------------------------
   5. REUSABLE BUTTONS
----------------------------------------- */

.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 13px;
  padding: 15px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  background: var(--forest);
  color: var(--white);
  font-size: 0.77rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  line-height: 1.3;
  text-align: center;
  text-transform: uppercase;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  background: var(--forest-deep);
  transform: translateY(-2px);
}

.button-light {
  border-color: var(--white);
  background: var(--white);
  color: var(--forest);
}

.button-light:hover {
  border-color: var(--sage-light);
  background: var(--sage-light);
  color: var(--forest-deep);
}

.button-outline {
  border-color: rgba(255, 255, 255, 0.8);
  background: transparent;
  color: var(--white);
}

.button-outline:hover {
  background: var(--white);
  color: var(--forest);
}

.button-arrow {
  font-size: 1.1rem;
  transition: transform var(--transition);
}

.button:hover .button-arrow {
  transform: translateX(4px);
}

/* -----------------------------------------
   6. FULL-BLEED HERO
----------------------------------------- */

.hero {
  position: relative;
  display: flex;
  min-height: min(790px, calc(100svh - 88px));
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--forest-deep);
  color: var(--white);
}

.hero__media {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
}

.hero__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 52%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(17, 39, 28, 0.88) 0%,
      rgba(17, 39, 28, 0.70) 43%,
      rgba(17, 39, 28, 0.18) 100%
    );
  content: "";
}

.hero-content {
  width: min(100% - var(--gutter) * 2, var(--container));
  margin-inline: auto;
  padding-block: 115px 130px;
  color: var(--white);
}

.hero .eyebrow {
  color: #d1ddc8;
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 27px;
  color: var(--white);
}

.hero h1 em {
  color: #d3dfc9;
  font-weight: 400;
}

.hero-description {
  max-width: 530px;
  margin-bottom: 36px;
  color: rgba(255, 255, 255, 0.9);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.85;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 15px;
}

.hero-note {
  margin-top: 35px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 0.76rem;
  letter-spacing: 0.06em;
}

/* -----------------------------------------
   7. INTRODUCTION / LANDSCAPE DESIGN
----------------------------------------- */

.intro-section {
  padding-block: var(--section-space);
  background: var(--cream);
}

.intro-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: clamp(55px, 9vw, 130px);
}

.intro-copy {
  max-width: 530px;
}

.intro-copy h2 {
  margin-bottom: 27px;
}

.intro-copy > p {
  color: var(--muted);
  font-size: 1.04rem;
  line-height: 1.95;
}

.intro-visual {
  position: relative;
  min-height: 440px;
  overflow: hidden;
  border-radius: var(--radius-medium);
  background: var(--sage-light);
}

.intro-visual img {
  width: 100%;
  height: 100%;
  min-height: 440px;
  object-fit: cover;
}

.intro-detail {
  position: absolute;
  right: 0;
  bottom: 0;
  max-width: 260px;
  padding: 25px 28px;
  background: var(--forest);
  color: var(--white);
}

.intro-detail strong {
  display: block;
  margin-bottom: 5px;
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 400;
}

.intro-detail span {
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.76rem;
  line-height: 1.6;
}

/* -----------------------------------------
   8. SERVICES
----------------------------------------- */

.services-section {
  padding-block: var(--section-space);
  background: var(--sand);
}

.services-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 58px;
}

.services-header .section-heading {
  margin-bottom: 0;
}

.services-header .section-copy {
  max-width: 390px;
  padding-bottom: 5px;
}

.services-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--line);
}

.service-item {
  position: relative;
  min-height: 235px;
  padding: 37px 34px 38px 0;
  border-bottom: 1px solid var(--line);
}

.service-item:not(:nth-child(3n)) {
  border-right: 1px solid var(--line);
}

.service-item:nth-child(3n + 2),
.service-item:nth-child(3n + 3) {
  padding-left: 34px;
}

.service-number {
  display: block;
  margin-bottom: 23px;
  color: var(--sage);
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-style: italic;
}

.service-item h3 {
  margin-bottom: 13px;
  font-size: 1.65rem;
}

.service-item p {
  max-width: 300px;
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.8;
}

/* -----------------------------------------
   9. FAMILY-OWNED / MAINTENANCE
----------------------------------------- */

.maintenance-section {
  position: relative;
  padding-block: var(--section-space);
  overflow: hidden;
  background: var(--forest);
  color: var(--white);
}

.maintenance-section h2 {
  color: var(--white);
}

.maintenance-section .eyebrow {
  color: #c1d1b8;
}

.maintenance-layout {
  display: grid;
  grid-template-columns: 1fr 0.85fr;
  align-items: center;
  gap: clamp(55px, 9vw, 125px);
}

.maintenance-copy {
  max-width: 590px;
}

.maintenance-copy h2 {
  margin-bottom: 27px;
}

.maintenance-copy > p {
  color: rgba(255, 255, 255, 0.78);
  font-size: 1rem;
  line-height: 1.95;
}

.maintenance-services {
  display: flex;
  flex-wrap: wrap;
  gap: 11px;
  margin-top: 30px;
}

.maintenance-services span {
  padding: 10px 15px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 3px;
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.77rem;
  letter-spacing: 0.04em;
}

.maintenance-visual {
  min-height: 410px;
  overflow: hidden;
  border-radius: var(--radius-medium);
  background: #354d3e;
}

.maintenance-visual img {
  width: 100%;
  height: 100%;
  min-height: 410px;
  object-fit: cover;
}

/* -----------------------------------------
   10. LOCAL MATERIALS / APPROACH
----------------------------------------- */

.approach-section {
  padding-block: var(--section-space);
  background: var(--cream);
}

.approach-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: center;
  gap: clamp(55px, 9vw, 120px);
}

.approach-visual {
  min-height: 410px;
  overflow: hidden;
  border-radius: var(--radius-medium);
  background: var(--sage-light);
}

.approach-visual img {
  width: 100%;
  height: 100%;
  min-height: 410px;
  object-fit: cover;
}

.approach-copy {
  max-width: 580px;
}

.approach-copy h2 {
  margin-bottom: 26px;
}

.approach-copy > p {
  color: var(--muted);
  font-size: 1.02rem;
  line-height: 1.9;
}

.approach-points {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 23px;
  margin-top: 35px;
  padding-top: 29px;
  border-top: 1px solid var(--line);
}

.approach-point strong {
  display: block;
  margin-bottom: 5px;
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 400;
}

.approach-point span {
  color: var(--muted);
  font-size: 0.8rem;
  line-height: 1.7;
}

/* -----------------------------------------
   11. LANDSCAPE DESIGN PROMOTION
----------------------------------------- */

.design-promotion {
  position: relative;
  padding-block: 85px;
  overflow: hidden;
  background: var(--sage-light);
}

.design-promotion-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 45px;
}

.design-promotion-copy {
  max-width: 700px;
}

.design-promotion h2 {
  margin-bottom: 17px;
  font-size: clamp(2.1rem, 4vw, 3.5rem);
}

.design-promotion p {
  max-width: 590px;
  color: var(--muted);
  font-size: 0.95rem;
  line-height: 1.8;
}

.design-promotion .button {
  flex-shrink: 0;
}

/* -----------------------------------------
   12. SHARED INTERACTION DETAILS
----------------------------------------- */

a,
button {
  transition:
    color var(--transition),
    background-color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

[ id ] {
  scroll-margin-top: 100px;
}
