/* CSS PART 2 OF 2 */

/* -----------------------------------------
   13. CONTACT / CONVERSION AREA
----------------------------------------- */

.contact-section {
  padding-block: var(--section-space);
  background: var(--sand);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(50px, 9vw, 120px);
}

.contact-copy {
  max-width: 470px;
}

.contact-copy h2 {
  margin-bottom: 25px;
}

.contact-copy > p {
  color: var(--muted);
  line-height: 1.9;
}

.contact-note {
  margin-top: 35px;
  padding-top: 24px;
  border-top: 1px solid var(--line);
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.3rem;
}

.contact-form {
  padding: clamp(25px, 4vw, 48px);
  border-radius: var(--radius-medium);
  background: var(--white);
  box-shadow: var(--shadow-soft);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--forest);
  font-size: 0.79rem;
  font-weight: 700;
  letter-spacing: 0.035em;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 53px;
  padding: 13px 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--cream);
  color: var(--ink);
  transition:
    border-color var(--transition),
    background-color var(--transition);
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #7b847d;
  opacity: 1;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--sage);
  background: var(--white);
}

.form-submit {
  margin-top: 25px;
}

.form-disclaimer {
  margin-top: 15px;
  color: var(--muted);
  font-size: 0.75rem;
  line-height: 1.6;
}

/* -----------------------------------------
   14. FOOTER
----------------------------------------- */

.site-footer {
  padding-block: 55px 28px;
  background: var(--forest-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 43px;
}

.footer-brand {
  max-width: 380px;
}

.footer-brand img {
  width: auto;
  max-width: 180px;
  max-height: 65px;
  object-fit: contain;
}

.footer-brand p {
  margin-top: 20px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.87rem;
  line-height: 1.8;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 22px 35px;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.82rem;
}

.footer-links a:hover {
  color: #d3dfc9;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 25px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.17);
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.73rem;
}

/* -----------------------------------------
   15. ACCESSIBLE MOBILE NAVIGATION
----------------------------------------- */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* -----------------------------------------
   16. RESPONSIVE TABLET
----------------------------------------- */

@media (max-width: 900px) {
  :root {
    --gutter: 34px;
    --section-space: 85px;
  }

  .header-inner {
    min-height: 78px;
    gap: 20px;
  }

  .primary-nav {
    gap: 17px;
  }

  .primary-nav a {
    font-size: 0.75rem;
  }

  .hero {
    min-height: 670px;
  }

  .intro-layout,
  .approach-layout {
    gap: 45px;
  }

  .maintenance-layout {
    gap: 40px;
  }

  .services-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 20px;
  }

  .services-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .service-item:not(:nth-child(3n)) {
    border-right: 0;
  }

  .service-item:nth-child(3n + 2),
  .service-item:nth-child(3n + 3) {
    padding-left: 0;
  }

  .service-item:nth-child(2n) {
    padding-left: 28px;
    border-left: 1px solid var(--line);
  }

  .service-item:nth-child(2n + 1) {
    padding-right: 28px;
  }

  .contact-layout {
    gap: 45px;
  }

  .design-promotion-inner {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* -----------------------------------------
   17. RESPONSIVE MOBILE NAVIGATION
----------------------------------------- */

@media (max-width: 680px) {
  :root {
    --gutter: 23px;
    --section-space: 72px;
  }

  html {
    scroll-padding-top: 76px;
  }

  .header-inner {
    position: relative;
    min-height: 74px;
  }

  .brand {
    min-width: 0;
    max-width: calc(100% - 65px);
  }

  .brand img {
    max-width: 155px;
    max-height: 52px;
  }

  .brand-name {
    font-size: 1.3rem;
  }

  .menu-toggle {
    display: flex;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: calc(100% + 1px);
    right: 0;
    left: 0;
    max-height: calc(100svh - 90px);
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 12px 22px 22px;
    border: 1px solid var(--line);
    border-top: 0;
    background: var(--cream);
    box-shadow: var(--shadow-soft);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a {
    display: block;
    width: 100%;
    padding: 13px 0;
    border-bottom: 1px solid var(--line);
    font-size: 0.85rem;
  }

  .primary-nav .button {
    width: 100%;
    margin-top: 15px;
    padding: 14px;
    border-bottom: 0;
  }

  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - 74px));
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(17, 39, 28, 0.87),
      rgba(17, 39, 28, 0.57)
    );
  }

  .hero__media img {
    object-position: 58% center;
  }

  .hero-content {
    padding-block: 85px 95px;
  }

  .hero h1 {
    max-width: 580px;
    font-size: clamp(3rem, 13vw, 4.7rem);
  }

  .hero-description {
    max-width: 440px;
    font-size: 0.96rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .intro-layout,
  .maintenance-layout,
  .approach-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .intro-visual,
  .intro-visual img {
    min-height: 310px;
  }

  .intro-detail {
    max-width: 215px;
    padding: 18px 20px;
  }

  .services-header {
    margin-bottom: 35px;
  }

  .services-list {
    grid-template-columns: 1fr;
  }

  .service-item,
  .service-item:nth-child(2n + 1),
  .service-item:nth-child(2n) {
    min-height: auto;
    padding: 27px 0;
    border-right: 0;
    border-left: 0;
  }

  .service-item:first-child {
    padding-top: 32px;
  }

  .service-number {
    margin-bottom: 13px;
  }

  .service-item h3 {
    font-size: 1.55rem;
  }

  .maintenance-visual,
  .maintenance-visual img,
  .approach-visual,
  .approach-visual img {
    min-height: 300px;
  }

  .approach-points {
    gap: 18px;
  }

  .design-promotion {
    padding-block: 65px;
  }

  .design-promotion h2 {
    font-size: 2.3rem;
  }

  .design-promotion .button {
    width: 100%;
  }

  .contact-form {
    padding: 24px 20px;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .form-field-full {
    grid-column: auto;
  }

  .form-submit,
  .form-submit .button {
    width: 100%;
  }

  .footer-main {
    flex-direction: column;
    gap: 30px;
  }

  .footer-links {
    gap: 15px 24px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 8px;
  }
}

/* -----------------------------------------
   18. SMALL MOBILE
----------------------------------------- */

@media (max-width: 380px) {
  :root {
    --gutter: 19px;
  }

  .hero h1 {
    font-size: 2.8rem;
  }

  .eyebrow {
    font-size: 0.65rem;
  }

  .approach-points {
    grid-template-columns: 1fr;
  }

  .button {
    padding-inline: 17px;
    font-size: 0.72rem;
  }

  .footer-links {
    flex-direction: column;
    gap: 12px;
  }
}

/* -----------------------------------------
   19. KEYBOARD FOCUS & MOTION PREFERENCES
----------------------------------------- */

:focus-visible {
  outline: 3px solid var(--earth);
  outline-offset: 4px;
}

.button:focus-visible,
.menu-toggle:focus-visible {
  outline-color: var(--earth);
  outline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
